# 全局 Pipeline 实例（延迟初始化，避免 import 时加载 MediaPipe 模型）
_pipeline = None

# 云端未显式传 algorithms 时，一次预处理后执行全部五项皮肤检测。
_DEFAULT_ALGORITHMS = [
    "redness",
    "spots",
    "brown",
    "texture",
    "pores",
]

# 对外正式返回。redness/spots 保持旧后端键兼容。
# 图片 / CSV 报告上传 OSS 返回 oss_key；
# metrics 为结构化量化数据，读取本地 JSON 解析成 dict inline 返回（不上传 OSS）。
_RESULT_UPLOAD_KEYS = (
    "redness",
    "red_areas_overlay",
    "redness_report",
    "spots",
    "spots_report",
    "brown",
    "brown_spots_overlay",
    "brown_report",
    "texture",
    "texture_report",
    "pores",
    "pores_report",
)
_METRICS_INLINE_KEYS = (
    "redness_metrics",
    "spots_metrics",
    "brown_metrics",
    "texture_metrics",
    "pores_metrics",
)
_RESULT_KEYS = _RESULT_UPLOAD_KEYS + _METRICS_INLINE_KEYS
