from pathlib import Path
roots=[Path('test-output/final_regression/spots'),Path('test-output/final_regression/redness'),Path('test-output/final_regression/brown_texture_pores_v2')]
images=jsons=csvs=0; failures=[]
for root in roots:
 for p in root.rglob('*'):
  if not p.is_file(): continue
  if p.suffix.lower() in {'.jpg','.jpeg','.png'}:
   images+=1
   if cv2.imread(str(p),cv2.IMREAD_UNCHANGED) is None or p.stat().st_size==0: failures.append(f'image:{p}')
  elif p.suffix.lower()=='.json':
   jsons+=1
   try: json.loads(p.read_text(encoding='utf-8-sig'))
   except Exception as e: failures.append(f'json:{p}:{e}')
  elif p.suffix.lower()=='.csv':
   csvs+=1
   try:
    rows=list(csv.reader(p.open(encoding='utf-8-sig')))
    if len(rows)!=2: failures.append(f'csv_rows:{p}:{len(rows)}')
    jp=p.with_suffix('.json')
    if jp.exists() and len(rows)==2:
     expected={h:int(v) for h,v in zip(rows[0],rows[1])}
     actual=json.loads(jp.read_text(encoding='utf-8-sig'))
     if expected!=actual: failures.append(f'mismatch:{p}')
   except Exception as e: failures.append(f'csv:{p}:{e}')
print({'images':images,'jsons':jsons,'csvs':csvs,'failures':failures})
